function normalizeWineLibraryLabelKey(label: string): string {
  return label
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[·']/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

const wineLibraryStrategicLabel = (label: string, lang: WineLibraryLang): string =>
  WINE_LIBRARY_STRATEGIC_LABELS[label]?.[lang]
  || (() => {
    const normalizedLabel = normalizeWineLibraryLabelKey(label);
    const matchingLabel = Object.keys(WINE_LIBRARY_STRATEGIC_LABELS)
      .find((candidate) => normalizeWineLibraryLabelKey(candidate) === normalizedLabel);

    return matchingLabel
      ? WINE_LIBRARY_STRATEGIC_LABELS[matchingLabel]?.[lang] || matchingLabel
      : label;
  })();

